#include <memory>
#include <vector>

class Data {};

void process(std::shared_ptr<Data> p) {
    // p increments the ref count
}

int main() {
    auto sp = std::make_shared<Data>(); // Ref count = 1
    {
        std::vector<std::shared_ptr<Data>> container;
        container.push_back(sp); // Ref count = 2
        container.push_back(sp); // Ref count = 3
    } // container destroyed, Ref count = 1 (Data persists)

    process(sp); // Ref count = 1 before, 2 during, 1 after
    // sp goes out of scope: Ref count = 0. Data destroyed.
}
